    if let Some((footprint, trace_id)) = ghostbridge_identity() {
        let md = request.metadata_mut();
        if let Ok(v) = footprint.parse() { md.insert("x-ghostbridge-footprint", v); }
        if let Ok(v) = trace_id.parse()  { md.insert("x-ghostbridge-trace-id", v); }
    }
}

