//! Static draft pages — the pre-finalisation authoring workflow.
//!
//! Until a page is finalised and minted into the gemma catalog, it lives as
//! a plain JSON file in `pages/<route>.json`, written in the exact same
//! json-render.dev DSL the interpreter consumes. Each file carries an
//! optional `data` payload — a canned stand-in for the live gRPC value
//! (gemma catalog stream, xray daemon, reflection services) — so `bind`
//! paths resolve while nothing is connected.
//!
//! Dev builds re-read changed files at runtime (throttled mtime scan), so
//! editing a page JSON and saving updates the running GUI without a rebuild.
//! Building with `--features embed-pages` compiles the same files into the
//! binary via `include_dir` and disables the disk scan — that is the
//! "finalise and embed" step; nothing about the page format changes.
//!
//! File format:
//! ```json
//! {
//!   "title": "optional human title",
//!   "spec":  { "kind": "stack", "children": [ ... ] },
//!   "data":  { "any": "static sample payload for bind paths" }
//! }
//! ```
//! The filename (minus `.json`, lowercase) must match the route's name,
//! e.g. `overview.json`, `grpc.json`, `privacynetwork.json`.

use std::collections::HashMap;
#[cfg(not(feature = "embed-pages"))]
use std::path::PathBuf;
#[cfg(not(feature = "embed-pages"))]
use std::time::{Duration, Instant, SystemTime};

use serde_json::Value;

use crate::nav::Route;

/// One parsed page file.
#[derive(Clone)]
pub struct StaticPage {
    pub spec: Value,
    pub data: Value,
    /// Parse error surfaced in the UI instead of the page.
    pub error: Option<String>,
}

pub struct StaticPages {
    pages: HashMap<String, StaticPage>,
    #[cfg(not(feature = "embed-pages"))]
    dir: Option<PathBuf>,
    #[cfg(not(feature = "embed-pages"))]
    mtimes: HashMap<String, SystemTime>,
    #[cfg(not(feature = "embed-pages"))]
    last_scan: Instant,
}

/// Route → page filename stem. Uses the enum variant name lowercased so no
/// per-route table needs maintaining.
pub fn route_slug(route: Route) -> String {
    format!("{route:?}").to_lowercase()
}

fn parse_page(slug: &str, raw: &str) -> StaticPage {
    match serde_json::from_str::<Value>(raw) {
        Ok(doc) => {
            let spec = doc.get("spec").cloned();
            match spec {
                Some(spec) => StaticPage {
                    spec,
                    data: doc.get("data").cloned().unwrap_or(Value::Null),
                    error: None,
                },
                None => StaticPage {
                    spec: Value::Null,
                    data: Value::Null,
                    error: Some(format!("pages/{slug}.json: missing top-level `spec` field")),
                },
            }
        }
        Err(e) => StaticPage {
            spec: Value::Null,
            data: Value::Null,
            error: Some(format!("pages/{slug}.json: {e}")),
        },
    }
}

#[cfg(feature = "embed-pages")]
mod embedded {
    use include_dir::{include_dir, Dir};
    pub static PAGES: Dir<'_> = include_dir!("$CARGO_MANIFEST_DIR/pages");
}

impl StaticPages {
    /// Embedded mode: pages compiled in at build time, no disk access.
    #[cfg(feature = "embed-pages")]
    pub fn new() -> Self {
        let mut pages = HashMap::new();
        for file in embedded::PAGES.files() {
            let name = file.path().file_stem().and_then(|s| s.to_str()).unwrap_or("");
            if file.path().extension().and_then(|e| e.to_str()) != Some("json") || name.is_empty() {
                continue;
            }
            if let Some(raw) = file.contents_utf8() {
                pages.insert(name.to_lowercase(), parse_page(name, raw));
            }
        }
        Self { pages }
    }

    /// Dev mode: resolve the pages directory and load whatever is there.
    /// Resolution order: `ZEROCLAW_GUI_PAGES` env var, `./pages` in the
    /// current directory, then `pages/` next to the crate source.
    #[cfg(not(feature = "embed-pages"))]
    pub fn new() -> Self {
        let dir = std::env::var_os("ZEROCLAW_GUI_PAGES")
            .map(PathBuf::from)
            .into_iter()
            .chain([PathBuf::from("pages"), PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/pages"))])
            .find(|p| p.is_dir());
        let mut s = Self {
            pages: HashMap::new(),
            dir,
            mtimes: HashMap::new(),
            last_scan: Instant::now() - Duration::from_secs(60),
        };
        s.scan(true);
        s
    }

    /// Look up the static page for a route, if one has been authored.
    pub fn get(&self, route: Route) -> Option<&StaticPage> {
        self.pages.get(&route_slug(route))
    }

    pub fn is_embedded(&self) -> bool {
        cfg!(feature = "embed-pages")
    }

    /// Throttled hot-reload tick. Call once per frame; actual disk work runs
    /// at most twice a second. No-op in embedded builds.
    #[cfg(not(feature = "embed-pages"))]
    pub fn tick(&mut self) {
        if self.last_scan.elapsed() >= Duration::from_millis(500) {
            self.scan(false);
        }
    }

    #[cfg(feature = "embed-pages")]
    pub fn tick(&mut self) {}

    #[cfg(not(feature = "embed-pages"))]
