        g.done = Some((kind, res));
        drop(g);
        ctx.request_repaint();
    });
}

pub fn render_gallery(
    ui: &mut egui::Ui,
    state: &mut GemmaGalleryState,
    catalog: &CatalogStore,
    registry: &ReflectionRegistry,
    ctx: &egui::Context,
) {
    // Drain a finished call.
    if let Some((kind, res)) = { state.slot.lock().done.take() } {
        match res {
            Ok(resp) => {
                let ok = resp.get("success").and_then(Value::as_bool).unwrap_or(false);
                let result = resp.get("result").cloned().unwrap_or(Value::Null);
                if !ok {
                    state.status = format!(
                        "gemma error: {}",
                        resp.get("error").map(|e| e.to_string()).unwrap_or_else(|| "unknown".into())
                    );
                } else {
                    let new = extract_elements(&result);
                    let n = new.len();
                    for el in new {
                        if !state.elements.iter().any(|e| e.id == el.id && e.version == el.version) {
                            state.elements.push(el);
                        }
                    }
                    state.status = match (kind, n) {
                        (CallKind::Refresh, 0) => "gallery refreshed — gemma returned no elements yet".into(),
                        (CallKind::Refresh, n) => format!("gallery refreshed — {n} element(s)"),
                        (CallKind::Prompt, 0) => format!("gemma replied without elements: {result}"),
                        (CallKind::Prompt, n) => format!("gemma minted {n} element(s)"),
                    };
                }
            }
            Err(e) => state.status = format!("call failed: {e}"),
        }
    }

    // Initial fetch on first open.
    if !state.fetched_once {
        state.fetched_once = true;
        state.status = "loading gallery from gemma_brain…".into();
        spawn_call(state, CallKind::Refresh, "get_ui_spec".into(), json!([]), registry.clone(), ctx.clone());
    }

    let in_flight = state.slot.lock().in_flight;

    // ---------- prompt bar ----------
    Frame::none()
        .fill(SURFACE)
        .stroke(Stroke::new(1.0, BORDER))
        .rounding(Rounding::same(8.0))
        .inner_margin(Margin::same(12.0))
        .show(ui, |ui| {
            ui.horizontal(|ui| {
                let prompt_w = (ui.available_width() - 320.0).max(200.0);
                let resp = ui.add_sized(
                    [prompt_w, 28.0],
                    TextEdit::singleline(&mut state.prompt)
                        .hint_text("Ask gemma for UI elements…")
                        .text_color(FG),
                );
                let submit = (resp.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter)))
                    || ui.add_enabled(!in_flight && !state.prompt.is_empty(),
                        egui::Button::new(RichText::new("Send").color(egui::Color32::WHITE))
                            .fill(PRIMARY).rounding(Rounding::same(6.0)).min_size(Vec2::new(64.0, 28.0)))
                        .clicked();
                if submit && !state.prompt.is_empty() && !in_flight {
                    let prompt = state.prompt.clone();
                    state.status = format!("sent to gemma_brain.{}…", state.prompt_method);
                    spawn_call(state, CallKind::Prompt, state.prompt_method.clone(),
                        json!([prompt]), registry.clone(), ctx.clone());
                }
                ui.add_space(8.0);
                ui.label(RichText::new("method").color(MUTED).size(10.0));
                ui.add_sized([120.0, 28.0], TextEdit::singleline(&mut state.prompt_method).text_color(FG));
                if ui.add_enabled(!in_flight, egui::Button::new("⟳ Refresh")).clicked() {
                    state.status = "refreshing gallery…".into();
                    spawn_call(state, CallKind::Refresh, "get_ui_spec".into(), json!([]),
                        registry.clone(), ctx.clone());
                }
            });
        });

    ui.add_space(6.0);
    ui.horizontal(|ui| {
        if in_flight { ui.spinner(); }
        ui.label(RichText::new(&state.status).color(MUTED).size(11.0));
        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
            let snap = catalog.snapshot();
            ui.label(RichText::new(format!(
                "{} in gallery · {} in catalog ({} stable-core)",
                state.elements.len(), snap.active.len(), snap.stable_core_count()
            )).color(MUTED).size(11.0));
        });
    });
    ui.add_space(10.0);

    // ---------- element cards, unbounded ----------
    if state.elements.is_empty() {
        ui.label(RichText::new("No elements yet — prompt gemma above.").color(MUTED).italics());
        return;
    }
    // Collect promote clicks to apply after the immutable iteration.
    let mut promote: Option<usize> = None;
    for (idx, el) in state.elements.iter().enumerate() {
        let promoted_v = state.promoted.get(&el.id).copied();
        Frame::none()
            .fill(SURFACE)
            .stroke(Stroke::new(1.0, BORDER))
            .rounding(Rounding::same(8.0))
            .inner_margin(Margin::same(14.0))
            .show(ui, |ui| {
                ui.horizontal(|ui| {
                    ui.label(RichText::new(&el.title).color(FG).strong().size(13.0));
                    ui.label(RichText::new(format!("{}@v{}", el.id, el.version)).color(MUTED).monospace().size(10.0));
                    let tier = match el.tier { Tier::StableCore => "stable-core", Tier::Novelty => "novelty" };
                    ui.label(RichText::new(tier).color(MUTED).size(10.0));
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        match promoted_v {
                            Some(v) => { ui.label(RichText::new(format!("✓ in catalog v{v}")).color(OK).size(11.0)); }
                            None => {
                                if ui.add(egui::Button::new(RichText::new("Promote to catalog").color(egui::Color32::WHITE).size(11.0))
                                    .fill(PRIMARY).rounding(Rounding::same(6.0))).clicked() {
                                    promote = Some(idx);
                                }
                            }
                        }
                    });
                });
                ui.add_space(8.0);
                ui.separator();
                ui.add_space(8.0);
                if let Err(e) = interpret::render_spec(ui, &el.spec, &Value::Null) {
                    ui.label(RichText::new(format!("render error: {e}")).color(DANGER).size(11.0).monospace());
                }
            });
        ui.add_space(10.0);
    }

    if let Some(idx) = promote {
        let el = state.elements[idx].clone();
        let id = el.id.clone();
        let version = el.version;
        let prior = catalog.admit(el);
        state.promoted.insert(id.clone(), version);
        state.status = match prior {
            Some(p) => format!("promoted {id}@v{version} (replaces v{p} in active gallery)"),
            None => format!("promoted {id}@v{version} to catalog"),
        };
    }
}

